arguments:
["func(w http.ResponseWriter, r *http.Request) {
	if isPublicDoc(r) {
		next.ServeHTTP(w, r)
		return
	}
	for _, c := range credentials(r) {
		if v.Verify(c.token) {
			if c.viaBasic {
				http.SetCookie(w, &http.Cookie{
					Name:     CookieName,
					Value:    c.token,
					Path:     "/",
					HttpOnly: true,
					SameSite: http.SameSiteStrictMode,
					Secure:   r.TLS != nil,
				})
			}
			next.ServeHTTP(w, r)
			return
		}
	}
	w.Header().Set("WWW-Authenticate", `Basic realm="termcp", charset="UTF-8"`)
	http.Error(w, "unauthorized: send Authorization: Bearer <token>, Basic with the token as password, or the termcp_token cookie", http.StatusUnauthorized)
}"]

callee_expression:
func() map[string]Capability {
	m := make(map[string]Capability, len(table))
	for _, c := range table {
		if _, dup := m[c.ID]; dup {
			panic("capability: duplicate id " + c.ID)
		}
		m[c.ID] = c
	}
	return m
}

func() map[string]string {
	m := make(map[string]string, len(toolIDs))
	for tool, id := range toolIDs {
		if _, seen := m[id]; !seen {
			m[id] = tool
		}
	}
	return m
}

