	defer w.leave()
	next.ServeHTTP(rw, r)
}"]

callee_expression:
func() map[string]Op {
	m := make(map[string]Op, len(ops))
	for _, op := range ops {
		m[op.Name] = op
		for _, alt := range op.AlsoKnownAs {
			m[alt] = op
		}
	}
	return m
}

